cat plan.md; mkdir -p restaurant-scheduler && cd restaurant-scheduler && printf "# Restaurant Shift Scheduler (prototype)\n\nSolves: last-minute call-outs and scheduling at 9pm texting (from parents' pain points).\n" > README.md && cat > scheduler.py << 'EOF'
"""Tiny shift scheduler prototype: fills shifts from staff availability, handles call-outs."""
from dataclasses import dataclass, field

@dataclass
class Staff:
    name: str
    available: set  # set of (day, shift) strings like ("Fri", "dinner")
    max_shifts: int = 5
    assigned: list = field(default_factory=list)

def build_schedule(staff, shifts):
    schedule = {s: [] for s in shifts}
    for s in shifts:
        for person in staff:
            if s in person.available and len(person.assigned) < person.max_shifts and len(schedule[s]) < 3:
                schedule[s].append(person.name)
                person.assigned.append(s)
    return schedule

def handle_callout(schedule, staff, shift, who):
    schedule[shift].remove(who)
    for person in staff:
        if person.name != who and shift in person.available and shift not in person.assigned and len(person.assigned) < person.max_shifts:
            schedule[shift].append(person.name)
            person.assigned.append(shift)
            return person.name
    return None  # no one free: owner gets alerted

if __name__ == "__main__":
    shifts = [("Fri", "dinner"), ("Sat", "dinner"), ("Sun", "lunch")]
    staff = [
        Staff("Ana", {("Fri", "dinner"), ("Sat", "dinner")}),
        Staff("Ben", {("Fri", "dinner"), ("Sun", "lunch")}),
        Staff("Cruz", {("Sat", "dinner"), ("Sun", "lunch")}),
    ]
    sched = build_schedule(staff, shifts)
    print(sched)
    print("Call-out:", handle_callout(sched, staff, ("Fri", "dinner"), "Ana"))
    print(sched)
EOF
python3 scheduler.py && cd .. && git init -q restaurant-scheduler 2>/dev/null; cd restaurant-scheduler && git add -A && git commit -qm "Shift scheduler prototype" && cd .. && echo ok

